            self.device = devices[0]
            self.is_running = True
            print("USB Device Found:", self.device.idVendor, self.device.idProduct)
        else:
            print("USB Device Not Found")

    def run(self):
        if self.device:
            try:
                self.device.ctrl_transfer(
                    ctrl_code = 0x01,  # USB Control Interface
                    ctrl_index = 0,   # Index for the controller
                    ctrl_value = 0x00, # Data for the transfer
                    data_len = 0      # Length of data to transfer
                )
            except Exception as e:
                print("Error occurred while receiving data:", e)

        while self.is_running:
            # Implement keystroke detection logic here
            pass

    def start(self):
        self.connect()
        self.run()
        while True:
            time.sleep(1)

    def stop(self):
        self.is_running = False

    def __enter__(self):
        self.start()
        return self

    def __exit__(self, type, value, traceback):
        self.stop()

